#!/usr/bin/env python3
"""
Falsifier for path traversal in bench.cdsfl_registry.registry.load_effective_policy.

This imports the real module, builds a minimal valid temporary registry, then
passes model="../evil_model". If the implementation joins the model string
without constraining it to REGISTRY_DIR/models, it will load
REGISTRY_DIR/evil_model.toml and inject an attacker-controlled policy section.

Prints FALSIFIED and raises AssertionError iff the traversal is actually
accepted and the out-of-directory TOML affects the returned policy.
"""

from __future__ import annotations

import json
import shutil
import tempfile
import warnings
from pathlib import Path
from typing import Any

import bench.cdsfl_registry.registry as reg


def _set_dotpath(root: dict[str, Any], dotpath: str, value: Any) -> None:
    cur = root
    parts = dotpath.split(".")
    for part in parts[:-1]:
        cur = cur.setdefault(part, {})
    cur[parts[-1]] = value


def _toml_scalar(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        return json.dumps(value)
    raise TypeError(f"unsupported TOML scalar in falsifier: {value!r}")


def _dump_toml_tables(data: dict[str, Any]) -> str:
    lines: list[str] = []

    def emit_table(table: dict[str, Any], path: tuple[str, ...]) -> None:
        scalars = {k: v for k, v in table.items() if not isinstance(v, dict)}
        children = {k: v for k, v in table.items() if isinstance(v, dict)}

        if path:
            lines.append(f"[{'.'.join(path)}]")
            for key, value in sorted(scalars.items()):
                lines.append(f"{key} = {_toml_scalar(value)}")
            lines.append("")
        else:
            for key, value in sorted(scalars.items()):
                lines.append(f"{key} = {_toml_scalar(value)}")
            if scalars:
                lines.append("")

        for key, child in sorted(children.items()):
            emit_table(child, path + (key,))

    emit_table(data, ())
    return "\n".join(lines)


def _minimal_valid_universal_toml() -> str:
    policy: dict[str, Any] = {}
    for dotpath, value in reg.HARD_CONSTRAINTS.items():
        _set_dotpath(policy, dotpath, value)
    for dotpath, value in reg.HARD_THRESHOLDS.items():
        _set_dotpath(policy, dotpath, value)
    for dotpath, value in reg.HARD_STRINGS.items():
        _set_dotpath(policy, dotpath, value)
    return _dump_toml_tables(policy)


def main() -> None:
    tmp = Path(tempfile.mkdtemp(prefix="cdsfl_registry_traversal_falsifier_"))

    # Snapshot before monkeypatching the real module global so the test is
    # isolated and does not poison later imports/tests.
    original_registry_dir = reg.REGISTRY_DIR

    try:
        (tmp / "models").mkdir()
        (tmp / "domains").mkdir()
        (tmp / "tasks").mkdir()

        # Precondition: universal policy itself is valid, so any successful
        # injection below is not caused by monotonicity failure/setup breakage.
        (tmp / "universal.toml").write_text(
            _minimal_valid_universal_toml(),
            encoding="utf-8",
        )

        # This file is deliberately outside tmp/models. A safe implementation
        # must not load it when model="../evil_model".
        (tmp / "evil_model.toml").write_text(
            """
[attacker]
path_traversal_model_loaded = true
""".strip()
            + "\n",
            encoding="utf-8",
        )

        reg.REGISTRY_DIR = tmp

        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            try:
                policy = reg.load_effective_policy(
                    domain="not-a-real-domain",
                    model="../evil_model",
                )
            except (FileNotFoundError, ValueError, reg.PolicyViolationError):
                # Clean exit: rejecting traversal or not finding a model under
                # models/ means this particular defect is absent.
                return

        if (
            isinstance(policy, dict)
            and policy.get("attacker", {}).get("path_traversal_model_loaded") is True
        ):
            msg = (
                "FALSIFIED: load_effective_policy accepted model='../evil_model' "
                "and loaded a TOML file outside REGISTRY_DIR/models."
            )
            print(msg)
            raise AssertionError(msg)

        # Clean exit: no out-of-directory attacker marker affected the policy.

    finally:
        reg.REGISTRY_DIR = original_registry_dir
        shutil.rmtree(tmp, ignore_errors=True)


if __name__ == "__main__":
    main()

