#!/usr/bin/env python3
"""
Falsifier for CC2_F601 in bench.evidence.

This reaches the real EvidenceStore.verify() path and detects whether a cached
successful verification silently survives an in-place mutation of the underlying
chain state. It prints FALSIFIED and raises AssertionError iff the defect is
present.
"""

from __future__ import annotations

import copy
import hashlib
import json
from typing import Any, Dict, List, Optional, Tuple

from bench.evidence import EvidenceStore


class ObservableDict(dict):
    """dict that bumps its owner's revision on in-place mutation."""

    def __init__(self, owner: "TamperAwareChain", initial: Dict[str, Any]):
        self._owner = owner
        dict.__init__(self, initial)

    def __setitem__(self, key: Any, value: Any) -> None:
        before = dict(self)
        dict.__setitem__(self, key, value)
        if dict(self) != before:
            self._owner._revision += 1

    def update(self, *args: Any, **kwargs: Any) -> None:
        before = dict(self)
        dict.update(self, *args, **kwargs)
        if dict(self) != before:
            self._owner._revision += 1


class TamperAwareChain:
    """
    Minimal chain double for EvidenceStore that behaves like a chain whose own
    verifier detects record tampering.

    EvidenceStore is the real target under test; this object supplies only the
    chain protocol EvidenceStore consumes.
    """

    def __init__(self) -> None:
        self._revision = 0
        metadata = ObservableDict(
            self,
            {
                "experiment": "cc2_f601",
                "model": "model-under-test",
                "round": 1,
            },
        )
        body = {
            "seq": 0,
            "artifact_type": "review_finding",
            "recorded_by": "cc2_f601_falsifier",
            "timestamp_utc": "2026-01-01T00:00:00Z",
            "storage_mode": "full_payload",
            "payload_hash": "sha256:" + hashlib.sha256(b"payload").hexdigest(),
            "metadata": metadata,
            "payload": {"finding_id": "C0601"},
        }
        self._records = [
            {
                "sealed_body": body,
                "chain_hash": "sha256:" + hashlib.sha256(b"record-0").hexdigest(),
            }
        ]
        self._epochs: List[Dict[str, Any]] = []
        self._sealed_fingerprint = self._fingerprint()

    @property
    def records(self) -> List[Dict[str, Any]]:
        # Match VerificationChain.records' intended copy-out behavior.
        return copy.deepcopy(json.loads(json.dumps(self._records)))

    @property
    def epochs(self) -> List[Dict[str, Any]]:
        return copy.deepcopy(self._epochs)

    @property
    def revision(self) -> int:
        return self._revision

    @property
    def version(self) -> int:
        return self._revision

    def _fingerprint(self) -> str:
        blob = json.dumps(self.records, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(blob).hexdigest()

    def verify_chain(self, verifier: Optional[Any] = None) -> Tuple[bool, str]:
        valid = self._fingerprint() == self._sealed_fingerprint
        return valid, "ok" if valid else "tamper detected"


def main() -> None:
    chain = TamperAwareChain()
    store = EvidenceStore(chain, experiment_name="cc2_f601")

    ok, msg = store.verify()
    if not ok:
        raise RuntimeError(f"bad falsifier setup: pristine chain did not verify: {msg}")

    # Snapshot BEFORE the in-place-mutating call.
    metadata_before = copy.deepcopy(chain._records[0]["sealed_body"]["metadata"])

    # In-place mutation of already-verified chain state.
    chain._records[0]["sealed_body"]["metadata"].update(
        {"tampered_after_cached_verify": True}
    )

    metadata_after = chain._records[0]["sealed_body"]["metadata"]
    if metadata_after == metadata_before:
        raise RuntimeError("bad falsifier setup: in-place mutation did not change metadata")

    directly_ok, directly_msg = chain.verify_chain()
    if directly_ok:
        raise RuntimeError(
            "bad falsifier setup: underlying chain verifier failed to detect tampering"
        )

    # This is the real buggy path: EvidenceStore.verify() may return its cached
    # prior success instead of re-running the underlying chain verification.
    cached_ok, cached_msg = store.verify()

    if cached_ok:
        print(
            "FALSIFIED CC2_F601: EvidenceStore.verify() returned cached success "
            "after the underlying chain was mutated in-place, even though "
            f"chain.verify_chain() now reports failure: {directly_msg!r}"
        )
        raise AssertionError("EvidenceStore.verify() cache masks chain tampering")


if __name__ == "__main__":
    main()

